formulas.expression:
OR(
    /* Matches 'Anruf von +[Any Number] (ohne Nachricht)' */
    REGEX({!$Record.Subject}, "Anruf von \\+\\d+ \\(ohne Nachricht\\)"),

    /* Matches 'Nachricht von +[Any Number] - Dauer: X Sekunden' where X <= 8 */
    AND(
        REGEX({!$Record.Subject}, "Nachricht von \\+\\d+ - Dauer: (\\d{1,2}) Sekunden"),
        VALUE(MID({!$Record.Subject}, FIND("Dauer: ", {!$Record.Subject}) + 7, FIND(" Sekunden", {!$Record.Subject}) - FIND("Dauer: ", {!$Record.Subject}) - 7)) <= 8
    )
)
